//**********************************



void	init_finder()	//encontrar posicion inicial
{
	int	i;
	int	j;
	
	printf("se ejecuta?\n");
	
	i = 0;
	j = 0;

	
	while (i < row_count)
	{
		j = 0;
		while (j < row_len)
		{
		
			
			//printf ("%c", mapa[i][j]);
			
				
				
			if (mapa[i][j] == '^')
			{
				row = i;
				col = j;
			}
			j++;
		}
		//printf("\n");
		
		//printf("%s\n", mapa[i]);
		i++;
	}
}


//**********************************
//**********************************

void	go_up()
{
	while (row >= 0)
	{
		if (row == 0)
		{
			out_of_bounds = 1;
			return ;
		}
		if (mapa[row - 1][col] == '#')
		{
			mapa[row][col] = '>';
			return ;
		}
		if (mapa[row-1][col] == '.')
			position++;
		mapa[row][col] = 'X';
		row--;
		mapa[row][col] = '^';
	}
}

void	go_right()
{
	while (col < row_len)
	{
		if (col == row_len - 1)
		{
			out_of_bounds = 1;
			return ;
		}
		if (mapa[row][col + 1] == '#')
		{
			mapa[row][col] = 'v';
			return ;
		}
		if (mapa[row][col + 1] == '.')
			position++;
		mapa[row][col] = 'X';
		col++;
		mapa[row][col] = '>';
	}
}


void	go_down()
{
	while (row < row_count)
	{
		if (row == row_count - 1)
		{
			out_of_bounds = 1;
			return ;
		}
		if (mapa[row + 1][col] == '#')
		{
			mapa[row][col] = '<';
			return ;
		}
		if (mapa[row + 1][col] == '.')
			position++;
		mapa[row][col] = 'X';
		row++;
		mapa[row][col] = 'v';
	}
}


void	go_left()
{
	while (col >= 0)
	{
		if (col == 0)
		{
			out_of_bounds = 1;
			return ;
		}
		if (mapa[row][col - 1] == '#')
		{
			mapa[row][col] = '^';
			return ;
		}
		if (mapa[row][col - 1] == '.')
			position++;
		mapa[row][col] = 'X';
		col--;
		mapa[row][col] = '<';
	}
}

