int	main()
{
	printf("el main no casca\n");
	mapa = ft_split(input, ';');
	printf("split funciona");
	map_counter();
	printf("dimensiones: %d : %d\n", row_count, row_len);
	init_finder();
	printf("posicion inicial : (%d , %d)\n", row, col);
	while (out_of_bounds == 0)
	{
		if (mapa[row][col] == '^')
			go_up();
		if (mapa[row][col] == '>')
			go_right();
		if (mapa[row][col] == 'v')
			go_down();
		if (mapa[row][col] == '<')
			go_left();
	}
	printf("posiciones recorridas: %d", position);
}
